PB;Heading 'ПРИЛОЖЕНИЕ А. ЛИСТИНГ ПРОГРАММЫ ARDUINO'
$code=@'
const int LDR_PIN=A0, NTC_PIN=A1, PIR_PIN=2;
const int RELAY_PIN=7, LED_PIN=13;
const unsigned long INTERVAL=15000UL;
unsigned long lastMillis=0, count=0; bool previousAlarm=false;
float mapFloat(float x,float a,float b,float c,float d){return (x-a)*(d-c)/(b-a)+c;}
void setup(){Serial.begin(9600);pinMode(PIR_PIN,INPUT);pinMode(RELAY_PIN,OUTPUT);pinMode(LED_PIN,OUTPUT);}
void loop(){
 if(millis()-lastMillis<INTERVAL)return; lastMillis=millis(); count++;
 int rawLight=analogRead(LDR_PIN), rawTemp=analogRead(NTC_PIN), motion=digitalRead(PIR_PIN);
 float light=mapFloat(rawLight,0,1023,0,100), temperature=mapFloat(rawTemp,0,1023,0,50);
 Serial.print("DATA n=");Serial.print(count);Serial.print(" s1=");Serial.print(light,1);
 Serial.print(" s2=");Serial.print(temperature,1);Serial.print(" s3=");Serial.println(motion);
 bool alarm=(motion==1 && light<30.0); digitalWrite(RELAY_PIN,alarm); digitalWrite(LED_PIN,alarm);
 if(alarm!=previousAlarm){Serial.print("EVENT n=");Serial.print(count);Serial.print(" type=");Serial.println(alarm?"THRESHOLD":"NORMAL");previousAlarm=alarm;}
}
'@
$r=$doc.Range();$r.Collapse(0);$r.Text=$code;$r.Font.Name='Courier New';$r.Font.Size=10;$r.ParagraphFormat.Alignment=0;$r.ParagraphFormat.LineSpacing=12
PB;Heading 'ПРИЛОЖЕНИЕ Б. SQL-СКРИПТ БАЗЫ ДАННЫХ'
$sql=@'
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS readings(id INTEGER PRIMARY KEY AUTOINCREMENT,n INTEGER NOT NULL,t_s INTEGER NOT NULL,sensor TEXT NOT NULL,value REAL NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,n INTEGER NOT NULL,t_s INTEGER NOT NULL,type TEXT NOT NULL,message TEXT);
CREATE INDEX IF NOT EXISTS idx_readings_sensor ON readings(sensor);
CREATE INDEX IF NOT EXISTS idx_events_type ON events(type);
SELECT sensor,MIN(value),AVG(value),MAX(value) FROM readings GROUP BY sensor;
SELECT * FROM events ORDER BY t_s;
'@
$r=$doc.Range();$r.Collapse(0);$r.Text=$sql;$r.Font.Name='Courier New';$r.Font.Size=10;$r.ParagraphFormat.Alignment=0;$r.ParagraphFormat.LineSpacing=12
$footer=$sec.Footers.Item(1).Range;$footer.ParagraphFormat.Alignment=2;$footer.Fields.Add($footer,33)
$file=Join-Path $out 'Курсовая_Ирпунова_Полина_вариант_11.docx'
$doc.SaveAs2($file,16);$doc.Close();$wd.Quit();Write-Output $file
